<?php require 'config.php';$n=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();if($n){header('Location: login.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<10)$err='Enter a name, valid email and password of at least 10 characters.';else{$s=$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'admin')");$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);header('Location: login.php');exit;}}layout_start('First-time administrator setup');?><section class="auth"><p>This one-time page creates the first administrator. It closes after setup.</p><?php if($err):?><p class="error"><?=e($err)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Full name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password (10+ characters)<input type="password" name="password" minlength="10" required></label><button>Create administrator</button></form></section><?php layout_end();?>